@layer components {
  .feed-page {
    max-width: var(--shelf-feedPage-maxWidth);
  }

  .feed-page-heading {
    color: var(--shelf-feedPage-fgColor-heading);
    font-size: var(--shelf-feedPage-fontSize-heading);
    font-weight: var(--shelf-feedPage-fontWeight-heading);
  }

  .feed-list {
    list-style: none;
  }

  .feed-item {
    background-color: var(--shelf-feedItem-bgColor-default);
    border: var(--shelf-feedItem-borderWidth) solid var(--shelf-feedItem-borderColor-default);
    border-radius: var(--shelf-feedItem-borderRadius);
    padding: var(--shelf-feedItem-padding);
  }

  .feed-item-title {
    color: var(--shelf-feedItem-fgColor-title);
    font-size: var(--shelf-feedItem-fontSize-title);
    font-weight: var(--shelf-feedItem-fontWeight-title);
  }

  .feed-item-description {
    color: var(--shelf-feedItem-fgColor-description);
    font-size: var(--shelf-feedItem-fontSize-description);
  }
}
